export default function ErgoWearApp() {
  const [tab, setTab] = useState("overview");
  const [connected, setConnected] = useState(true);
  const [battery, setBattery] = useState(87);
  const [angle, setAngle] = useState(8);
  const [displayAngle, setDisplayAngle] = useState(8);
  const [loaded, setLoaded] = useState(false);
  const [history, setHistory] = useState(() =>
    Array.from({ length: 24 }, (_, i) => ({ t: i, angle: 8 }))
  );
  const [session, setSession] = useState(0);
  const [badPostureSeconds, setBadPostureSeconds] = useState(0);
  const [flagged, setFlagged] = useState(false);
  const [flash, setFlash] = useState(false);
  const [events, setEvents] = useState([]);
  const [deviationCount, setDeviationCount] = useState(0);
  const [totalBadSeconds, setTotalBadSeconds] = useState(0);
  const [riskScore, setRiskScore] = useState(0);
  const [thresholds, setThresholds] = useState({ angle: 20, duration: 3 });
  const [selectedWorker, setSelectedWorker] = useState(WORKERS[0]);
  const [susResults, setSusResults] = useState([]);

  const phase = useRef(0);
  const tCounter = useRef(24);
  const flashTimer = useRef(null);
  const angleRef = useRef(8);

  // simulate initial device handshake / loading
  useEffect(() => {
    const id = setTimeout(() => setLoaded(true), 900);
    return () => clearTimeout(id);
  }, []);

  useEffect(() => {
    angleRef.current = angle;
  }, [angle]);

  // smooth easing loop so the spine gauge bends fluidly between samples
  useEffect(() => {
    let raf;
    const loop = () => {
      setDisplayAngle((d) => {
        const target = angleRef.current;
        const nd = d + (target - d) * 0.12;
        return Math.abs(nd - target) < 0.05 ? target : nd;
      });
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);

  const tick = useCallback(() => {
    if (!connected) return;

    // simulate posture angle: slow drift + occasional excursions
    phase.current += 0.35;
    const wobble = Math.sin(phase.current) * 6 + Math.sin(phase.current * 0.31) * 10;
    const spikeWindow = Math.floor(phase.current) % 14;
    const spike = spikeWindow < 4 ? spikeWindow * 6 : 0;
    const noise = (Math.random() - 0.5) * 4;
    let next = Math.max(2, Math.min(48, 12 + wobble * 0.6 + spike + noise));
    next = Math.round(next);
    setAngle(next);

    tCounter.current += 1;
    setHistory((h) => {
      const nh = [...h, { t: tCounter.current, angle: next }];
      return nh.slice(-30);
    });

    setSession((s) => s + 1);

    const zone = zoneFor(next, thresholds);
    if (next > thresholds.angle) {
      setTotalBadSeconds((v) => v + 1);
      setBadPostureSeconds((prev) => {
        const nv = prev + 1;
        if (nv >= thresholds.duration && !flagged) {
          setFlagged(true);
          setDeviationCount((c) => c + 1);
          setRiskScore((r) => Math.min(100, r + (next - thresholds.angle) * 1.2));
          setFlash(true);
          if (flashTimer.current) clearTimeout(flashTimer.current);
          flashTimer.current = setTimeout(() => setFlash(false), 1400);
          const now = new Date();
          setEvents((ev) => [
            {
              id: `${now.getTime()}`,
              time: now.toLocaleTimeString("id-ID"),
              angle: next,
              zone: zone.label,
            },
            ...ev,
          ].slice(0, 12));
        }
        return nv;
      });
    } else {
      setBadPostureSeconds(0);
      setFlagged(false);
    }

    setBattery((b) => Math.max(12, +(b - 0.03).toFixed(2)));
  }, [connected, thresholds, flagged]);

  useEffect(() => {
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [tick]);

  const zone = zoneFor(angle, thresholds);

  const navItems = [
    { id: "overview", label: "Overview", icon: Radio },
    { id: "dashboard", label: "Dasbor", icon: Activity },
    { id: "riwayat", label: "Riwayat", icon: History },
    { id: "pekerja", label: "Pekerja", icon: Users },
    { id: "alat", label: "Alat", icon: Cpu },
    { id: "pengaturan", label: "Pengaturan", icon: Settings },
  ];

  if (!loaded) return <LoadingScreen />;

  return (
    <div
      className="min-h-screen w-full flex"
      style={{ background: C.bg, color: C.text, fontFamily: "Inter, sans-serif" }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; }
        ::-webkit-scrollbar { width: 6px; height: 6px; }
        ::-webkit-scrollbar-thumb { background: ${C.border}; border-radius: 6px; }
        .oswald { font-family: 'Oswald', sans-serif; }
        input[type=range] { -webkit-appearance: none; height: 4px; border-radius: 4px; background: ${C.border}; }
        input[type=range]::-webkit-slider-thumb {
          -webkit-appearance: none; width: 18px; height: 18px; border-radius: 50%;
          background: ${C.amber}; cursor: pointer; border: 3px solid ${C.bg};
          box-shadow: 0 0 0 1px ${C.amber};
        }
        @keyframes pulseBg { 0%,100% { opacity: .18 } 50% { opacity: .38 } }
        @keyframes numberPulse { 0%,100% { transform: scale(1); } 50% { transform: scale(1.06); } }
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
        .flash-number { animation: numberPulse 0.7s ease-in-out 2; }
        .fade-in { animation: fadeInUp 0.35s ease both; }
        .zone-transition { transition: background-color .5s ease, border-color .5s ease, color .5s ease; }
        .grain-layer {
          position: fixed; inset: 0; pointer-events: none; z-index: 0; opacity: 0.05;
          background-image:
            repeating-linear-gradient(100deg, #F3EEE3 0px, #F3EEE3 1px, transparent 1px, transparent 4px),
            repeating-linear-gradient(96deg, #000 0px, #000 1px, transparent 1px, transparent 7px);
          mix-blend-mode: overlay;
        }
        @media print {
          body * { visibility: hidden; }
          #laporan-print, #laporan-print * { visibility: visible; }
          #laporan-print { position: absolute; left: 0; top: 0; width: 100%; padding: 24px; }
        }
      `}</style>
      <div className="grain-layer" />

      {/* Desktop sidebar */}
      <aside
        className="hidden md:flex w-60 flex-col shrink-0 border-r p-5"
        style={{ borderColor: C.border, background: C.bgElev }}
      >
        <div className="flex items-center gap-2 mb-8">
          <SpineGauge angle={12} color={C.amber} size={54} />
          <div>
            <div className="oswald text-lg leading-none tracking-wide">ERGO-WEAR</div>
            <div className="text-[10px] uppercase tracking-widest" style={{ color: C.muted }}>
              Postur · K3 UMKM
            </div>
          </div>
        </div>
        <nav className="flex flex-col gap-1">
          {navItems.map((n) => {
            const Icon = n.icon;
            const active = tab === n.id;
            return (
              <button
                key={n.id}
                onClick={() => setTab(n.id)}
                className="flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm transition-colors"
                style={{
                  background: active ? `${C.amber}1F` : "transparent",
                  color: active ? C.amber : C.muted,
                  fontWeight: active ? 600 : 500,
                }}
              >
                <Icon size={17} />
                {n.label}
                {active && <ChevronRight size={14} className="ml-auto" />}
              </button>
            );
          })}
        </nav>

        <div className="mt-auto pt-6 border-t" style={{ borderColor: C.border }}>
          <button
            onClick={() => setConnected((c) => !c)}
            className="w-full flex items-center gap-2 px-3 py-2.5 rounded-xl text-sm"
            style={{
              background: connected ? `${C.safe}18` : `${C.danger}18`,
              color: connected ? C.safe : C.danger,
            }}
          >
            {connected ? <Wifi size={16} /> : <WifiOff size={16} />}
            {connected ? "Perangkat Terhubung" : "Perangkat Terputus"}
          </button>
        </div>
      </aside>

      {/* Main column */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Top bar */}
        <header
          className="flex items-center justify-between px-4 md:px-8 py-4 border-b sticky top-0 z-10"
          style={{ borderColor: C.border, background: `${C.bg}EE`, backdropFilter: "blur(6px)" }}
        >
          <div className="flex items-center gap-3 md:hidden">
            <SpineGauge angle={12} color={C.amber} size={38} />
            <span className="oswald text-base tracking-wide">ERGO-WEAR</span>
          </div>
          <div className="hidden md:block">
            <div className="text-xs uppercase tracking-widest" style={{ color: C.muted }}>
              Sesi kerja &middot; {selectedWorker.name}
            </div>
            <div className="oswald text-xl">
              {tab === "overview"
                ? "Product Overview"
                : tab === "dashboard"
                ? "Pemantauan Real-Time"
                : tab === "riwayat"
                ? "Riwayat & Tren"
                : tab === "pekerja"
                ? "Perbandingan Pekerja"
                : tab === "alat"
                ? "Spesifikasi Perangkat"
                : "Pengaturan Ambang Batas"}
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Pill color={connected ? C.safe : C.danger}>
              {connected ? <Wifi size={12} /> : <WifiOff size={12} />}
              {connected ? "Online" : "Offline"}
            </Pill>
            <Pill color={battery < 25 ? C.danger : C.muted}>
              {battery < 25 ? <BatteryLow size={12} /> : <BatteryMedium size={12} />}
              {battery.toFixed(0)}%
            </Pill>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8">
          {tab === "overview" && (
            <OverviewTab onOpenDashboard={() => setTab("dashboard")} onOpenDemo={() => document.getElementById("ergowear-demo")?.scrollIntoView({ behavior: "smooth" })} />
          )}
          {tab === "dashboard" && (
            <DashboardTab
              angle={angle}
              displayAngle={displayAngle}
              zone={zone}
              history={history}
              thresholds={thresholds}
              badPostureSeconds={badPostureSeconds}
              session={session}
              deviationCount={deviationCount}
              riskScore={riskScore}
              flash={flash}
              events={events}
              connected={connected}
            />
          )}
          {tab === "riwayat" && (
            <RiwayatTab
              history={history}
              thresholds={thresholds}
              totalBadSeconds={totalBadSeconds}
              deviationCount={deviationCount}
              session={session}
              events={events}
              riskScore={riskScore}
              worker={selectedWorker}
            />
          )}
          {tab === "pekerja" && (
            <PekerjaTab
              workers={WORKERS}
              selectedWorker={selectedWorker}
              setSelectedWorker={setSelectedWorker}
              susResults={susResults}
              setSusResults={setSusResults}
            />
          )}
          {tab === "alat" && <AlatTab thresholds={thresholds} />}
          {tab === "pengaturan" && (
            <PengaturanTab
              thresholds={thresholds}
              setThresholds={setThresholds}
              connected={connected}
              setConnected={setConnected}
              battery={battery}
            />
          )}
        </main>
      </div>

      {/* Mobile bottom nav */}
      <nav
        className="md:hidden fixed bottom-0 left-0 right-0 flex items-stretch border-t z-20"
        style={{ borderColor: C.border, background: C.bgElev }}
      >
        {navItems.map((n) => {
          const Icon = n.icon;
          const active = tab === n.id;
          return (
            <button
              key={n.id}
              onClick={() => setTab(n.id)}
              className="flex-1 flex flex-col items-center gap-1 py-2.5"
              style={{ color: active ? C.amber : C.muted }}
            >
              <Icon size={19} />
              <span className="text-[10px]">{n.label}</span>
            </button>
          );
        })}
      </nav>
    </div>
  );
}

